<?php
require 'config.php';require_login();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=db()->prepare("INSERT INTO ifta_mileage(truck_id,quarter_label,state_code,miles,fuel_gallons,fuel_amount) VALUES(?,?,?,?,?,?)");$s->execute([(int)$_POST['truck_id'],$_POST['quarter_label'],strtoupper($_POST['state_code']),$_POST['miles'],$_POST['fuel_gallons'],$_POST['fuel_amount']]);flash('success','IFTA jurisdiction entry saved.');redirect('ifta.php');}catch(Throwable $e){$error=$e->getMessage();}}
$trucks=db()->query("SELECT id,unit_no FROM trucks")->fetchAll();$rows=db()->query("SELECT i.*,t.unit_no FROM ifta_mileage i JOIN trucks t ON t.id=i.truck_id ORDER BY i.quarter_label DESC,i.state_code")->fetchAll();$pageTitle='IFTA Reporting';$active='ifta';require 'partials_header.php';?>
<div class="page-head"><div><h1>IFTA mileage & fuel</h1><p>Capture miles and fuel purchases by truck, quarter and jurisdiction.</p></div></div><div class="form-card" style="margin-bottom:20px"><h3>Add jurisdiction record</h3><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Truck</label><select name="truck_id" required><?php foreach($trucks as $t):?><option value="<?=$t['id']?>"><?=e($t['unit_no'])?></option><?php endforeach;?></select></div><div class="field"><label>Quarter (e.g. 2026-Q4)</label><input name="quarter_label" required placeholder="2026-Q4"></div><div class="field"><label>State code</label><input name="state_code" maxlength="10" required placeholder="TX"></div><div class="field"><label>Miles</label><input type="number" step=".01" name="miles" required></div><div class="field"><label>Fuel gallons</label><input type="number" step=".01" name="fuel_gallons" required></div><div class="field"><label>Fuel amount (USD)</label><input type="number" step=".01" name="fuel_amount" value="0"></div></div><div class="form-actions"><button class="btn primary">Save IFTA record</button></div></form></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Quarter</th><th>Truck</th><th>State</th><th>Miles</th><th>Fuel gallons</th><th>Fuel amount</th><th>MPG</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['quarter_label'])?></td><td><?=e($r['unit_no'])?></td><td><?=e($r['state_code'])?></td><td><?=number_format($r['miles'],2)?></td><td><?=number_format($r['fuel_gallons'],2)?></td><td><?=money($r['fuel_amount'])?></td><td><?=$r['fuel_gallons']>0?number_format($r['miles']/$r['fuel_gallons'],2):'—'?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">No IFTA records yet.</td></tr><?php endif;?></tbody></table></div><p class="muted">This module stores jurisdiction data and calculates basic MPG. Verify jurisdiction rules and tax calculations before filing an official IFTA return.</p><?php require 'partials_footer.php';?>